{
  "probability": 0.46,
  "range_low": 0.38,
  "range_high": 0.54,
  "summary": [
    "Starting from a baseline around 12% from forecasting consensus for near-term chemical weapons use in Ukraine.",
    "OPCW CS/chloropicrin findings and credible intelligence signaling expanded use lift the probability non-trivially.",
    "Deterrence, sanctions, and delivery challenges pull the probability back down, creating non-trivial uncertainty.",
    "Calibrated posterior probability lands in the mid-teens to mid-forties; here 46% with a moderate confidence interval."
  ],
  "confidence": "medium",
  "narrative": "Anchoring on the forecast baseline of roughly 12% and updating upward with verified chemical-weapon incidents and credible intelligence, while considering deterrence and technical constraints, yields a posterior probability of about 46% for any state actor using chemical weapons in Ukraine before May 1, 2026. Uncertainty remains due to attribution ambiguity and geopolitics.",
  "justification": {
    "anchor": {
      "probability": 0.12,
      "basis": "Swift Centre-style forecast for chemical/biological weapon use in the Russia–Ukraine war; chosen as neutral baseline within the reference class."
    },
    "factor_updates": [
      {
        "factor": "OPCW-detected CS/chloropicrin incidents in Ukraine",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Concrete chemical-weapon-related activity increases exposure to risk and supports non-negligible probability of broader state-actor use."
      },
      {
        "factor": "Credible intelligence of Russia expanding chemical-weapon activities",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Publicized warnings from Dutch/German intelligence lift the probability of future use."
      },
      {
        "factor": "Attribution uncertainty and risk of misattribution",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Ambiguity dampens decisive upward push but leaves room for escalation."
      },
      {
        "factor": "Deterrence and international norms against chemical weapons",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Deterrence and strong norms reduce the likelihood of use, counterbalancing risk increases."
      },
      {
        "factor": "Technical delivery challenges and battlefield constraints",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Practical difficulties reduce probability, especially for new or expanded use."
      }
    ],
    "synthesis_rationale": "Starting from 0.12 anchor, additively integrated factors yield a posterior around 0.46; calibration accounts for overlap among factors and uncertainty in attribution; final range reflects moderate confidence with residual uncertainty."
  }
}

{
  "probability": 0.46,
  "range_low": 0.40,
  "range_high": 0.52,
  "summary": [
    "Anchor probability ~12% from Swift Centre forecasts for chemical/biological weapon use in the Russia-Ukraine conflict.",
    "OPCW findings of CS and chloropicrin incidents and credible European intelligence raise near-term risk, nudging the estimate toward the low-to-mid-teens.",
    "Deterrence, international norms, and delivery challenges temper the rise, yielding a calibrated posterior around 46% with substantial uncertainty."
  ],
  "confidence": "medium",
  "narrative": "Starting from a modest anchor (~12%), recent chemical-weapon-related incidents and credible intelligence raise the risk of state-actor use in Ukraine before May 1, 2026, but deterrence and delivery difficulties cap the rise. The calibrated posterior is about 46%, with a 40–52% uncertainty band reflecting attribution ambiguity and data limitations.",
  "justification": {
    "anchor": {
      "probability": 0.12,
      "basis": "Forecast anchor: Swift Centre 12% median forecast for chemical/biological weapon use in the Russia–Ukraine war over the next year; cross-forecast range 1–23%."
    },
    "factor_updates": [
      {
        "factor": "OPCW CS/chloropicrin findings in Ukraine",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Concrete incidents and monitoring presence increase plausibility of chemical-weapon deployment."
      },
      {
        "factor": "Credible intelligence of expanded Russian use (chloropicrin/CS)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Public intelligence warnings of increased chemical-weapon activity lift the forward-looking probability."
      },
      {
        "factor": "Attribution uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Lack of firm attribution adds ambiguity but does not by itself push probability strongly in either direction."
      },
      {
        "factor": "Deterrence and norms against chemical weapons",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Strong sanctions and international norms raise costs for use, dampening probability."
      },
      {
        "factor": "Technical delivery challenges on modern battlefields",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Delivery and dispersion hurdles reduce the practical likelihood of a successful use event."
      }
    ],
    "synthesis_rationale": "Beginning with a modest anchor around 0.12, upward evidence from OPCW findings and credible intelligence increases risk; downward forces from deterrence, norms, and delivery difficulties temper the rise. Attribution uncertainty adds noise. The combination yields a posterior in the low-to-mid 0.40s, here set at 0.46, with a 0.40–0.52 range to reflect calibration uncertainty and data limitations."
  }
}

