    "factor_updates": [
      {
        "factor": "OPCW CS/riot-control agent findings on Ukraine front lines",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "OPCW detects CS and related agents in Ukraine incidents, increasing plausibility of chemical-weapon deployment."
      },
      {
        "factor": "Credible intelligence on Russia expanding chemical weapon use (chloropicrin/CS)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Public warnings from European intelligence widen the plausible activity profile, supporting higher probability."
      },
      {
        "factor": "Attribution uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Lack of conclusive attribution reduces certainty; could swing up or down with new evidence."
      },
      {
        "factor": "International sanctions and normative costs",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Deterrence and costs for use push probability downward."
      },
      {
        "factor": "Delivery challenges and battlefield feasibility",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Technical and logistical hurdles reduce practical likelihood."
      }
    ],
    "synthesis_rationale": "We start from anchor 0.12; add upward contributions from OPCW findings and credible intelligence, subtract downward pressures from deterrence, delivery constraints, and attribution uncertainty (neutral). The net effect yields a probability around 0.18 with a plausible range of 0.10–0.28; calibration notes reflect that real-world evidence remains uncertain and contested, so the final estimate is hedged."
  }
}
